mongodb:createCollection.mongodb:options:
{
    validator: {
        $jsonSchema: {
            bsonType: "object",
            required: ["bookId", "rating"],
            properties: {
                bookId:    { bsonType: "string" },
                rating:    { bsonType: "int", minimum: 1, maximum: 5 },
                comment:   { bsonType: "string" },
                createdAt: { bsonType: "date" }
            }
        }
    }
}

mongodb:runCommand.mongodb:command:
{
    collMod: "books",
    validator: {
        $jsonSchema: {
            bsonType: "object",
            required: ["title", "authorId"],
            properties: {
                title:         { bsonType: "string", description: "Book title" },
                authorId:      { bsonType: "string", description: "Reference to authors collection" },
                isbn:          { bsonType: "string", description: "ISBN-13" },
                pages:         { bsonType: "int",    description: "Page count" },
                publishedYear: { bsonType: "int",    description: "Year of publication" }
            }
        }
    },
    validationLevel: "moderate"
}

{
    collMod: "books",
    validator: {
        $jsonSchema: {
            bsonType: "object",
            required: ["title", "authorId"],
            properties: {
                title:    { bsonType: "string", description: "Book title" },
                authorId: { bsonType: "string", description: "Reference to authors collection" },
                isbn:     { bsonType: "string", description: "ISBN-13" },
                pages:    { bsonType: "int",    description: "Page count" }
            }
        }
    },
    validationLevel: "moderate"
}

{
    update: "books",
    updates: [
        { q: { _id: "book-001" }, u: { $set: { publishedYear: 2018 } } },
        { q: { _id: "book-002" }, u: { $set: { publishedYear: 2008 } } },
        { q: { _id: "book-003" }, u: { $set: { publishedYear: 2017 } } }
    ]
}

{
    update: "books",
    updates: [
        { q: { _id: "book-001" }, u: { $unset: { publishedYear: "" } } },
        { q: { _id: "book-002" }, u: { $unset: { publishedYear: "" } } },
        { q: { _id: "book-003" }, u: { $unset: { publishedYear: "" } } }
    ]
}
